import{_ as e,o,c as a,ag as r}from"./chunks/framework.wGDfT7ie.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"zkde.fi","text":"Privacy-preserving DeFi on Starknet","tagline":"zkDE + GATE. Proof-gated execution. Selective disclosure. Confidential positions. By Obsqra Labs.","actions":[{"theme":"brand","text":"Get started","link":"/intro"},{"theme":"alt","text":"Open app","link":"https://zkde.fi","target":"_blank"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,t,d,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="what-is-zkde-fi" tabindex="-1">What is zkde.fi? <a class="header-anchor" href="#what-is-zkde-fi" aria-label="Permalink to &quot;What is zkde.fi?&quot;">​</a></h2><p><strong>zkde.fi</strong> is the first <strong>GATE-compatible</strong> app: a privacy-preserving autonomous agent for DeFi on Starknet, built on <strong>zkDE (Zero-Knowledge Deterministic Engine)</strong> and <strong>GATE (Governed Autonomous Trustless Execution)</strong>. zkDE is the engine where execution is proof-gated and verification is deterministic; GATE is the standard for how agents operate in that engine. You set constraints; the agent allocates across protocols; every action is <strong>proof-gated</strong> (verified on-chain) and <strong>privacy-preserving</strong> (intent-hiding, confidential balances, selective disclosure).</p><h3 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h3><ul><li><strong>zkML Models</strong> — AI-driven decisions with hidden model outputs. Risk score and anomaly detection gate actions.</li><li><strong>Proof-gating</strong> — No proof, no execution. Both zkML (Garaga) and execution (Integrity) proofs required.</li><li><strong>Session keys</strong> — Delegate once; agent acts within your limits (max position, protocols, duration).</li><li><strong>Intent commitments</strong> — Replay-safe and fork-safe execution.</li><li><strong>Selective disclosure</strong> — Prove compliance without revealing your full history.</li><li><strong>Confidential transfers</strong> — Amounts and balances stay off the public ledger (Garaga on Sepolia).</li></ul><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Proof System</th><th>Purpose</th></tr></thead><tbody><tr><td>Privacy</td><td>Garaga (Groth16)</td><td>zkML proofs, confidential transfers</td></tr><tr><td>Execution</td><td>Integrity (STARK)</td><td>Constraint proofs, receipts</td></tr></tbody></table><p><a href="/docs/intro.html">Read the docs</a> | <a href="/docs/zkml-models.html">zkML Models</a> | <a href="/docs/session-keys.html">Session Keys</a></p>',7)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
